'use strict';

// Sanity check that independently soft-deleted Posts are NOT restored when the
// owning User is restored. Not exercised by the HTTP API (there is no endpoint
// to soft-delete a single Post) but a worthwhile guard.
const path = require('path');
const { Sequelize, DataTypes } = require('sequelize');

const sequelize = new Sequelize({
  dialect: 'sqlite',
  storage: path.join(__dirname, 'database.sqlite'),
  logging: false,
});

const Post = sequelize.define(
  'Post',
  {
    title: DataTypes.STRING,
    cascadeDeletedAt: DataTypes.DATE,
  },
  { paranoid: true }
);

const User = sequelize.define(
  'User',
  { username: DataTypes.STRING },
  { paranoid: true }
);

User.hasMany(Post, { foreignKey: { allowNull: false } });
Post.belongsTo(User);

User.afterDestroy(async (user, options) => {
  const cascadeAt = user.dataValues.deletedAt || new Date();
  await Post.update(
    { deletedAt: cascadeAt, cascadeDeletedAt: cascadeAt },
    {
      where: { UserId: user.id, deletedAt: null },
      paranoid: false,
      transaction: options.transaction,
    }
  );
});

User.beforeRestore(async (user, options) => {
  const cascadeAt = user.dataValues.deletedAt;
  await Post.update(
    { deletedAt: null, cascadeDeletedAt: null },
    {
      where: { UserId: user.id, cascadeDeletedAt: cascadeAt },
      paranoid: false,
      transaction: options.transaction,
    }
  );
});

(async () => {
  await sequelize.sync({ force: true });
  const user = await User.create({ username: 'bob' });
  const p1 = await Post.create({ title: 'p1', UserId: user.id });
  const p2 = await Post.create({ title: 'p2', UserId: user.id });

  // Independently soft-delete p1 first
  await p1.destroy();
  const p1Before = await Post.findByPk(p1.id, { paranoid: false });
  console.log('p1 deletedAt (independent):', p1Before.deletedAt, 'cascadeDeletedAt:', p1Before.cascadeDeletedAt);

  // Now soft-delete the User -> should cascade only to p2
  await user.destroy();

  const p1After = await Post.findByPk(p1.id, { paranoid: false });
  const p2After = await Post.findByPk(p2.id, { paranoid: false });
  console.log('p1 after User delete -> deletedAt:', p1After.deletedAt, '(should be UNCHANGED)');
  console.log('p2 after User delete -> deletedAt:', p2After.deletedAt, 'cascadeDeletedAt:', p2After.cascadeDeletedAt);

  // Restore the User -> should restore p2 only
  await user.restore();
  const p1Restored = await Post.findByPk(p1.id, { paranoid: false });
  const p2Restored = await Post.findByPk(p2.id, { paranoid: false });
  console.log('p1 after User restore -> deletedAt:', p1Restored.deletedAt, '(should be NOT null - independent delete preserved)');
  console.log('p2 after User restore -> deletedAt:', p2Restored.deletedAt, '(should be null)');

  // Final assertions
  const p1StillDeleted = p1Restored.deletedAt !== null;
  const p2Active = await Post.findByPk(p2.id) !== null;
  console.log('ASSERT p1 still deleted:', p1StillDeleted);
  console.log('ASSERT p2 active again:', p2Active);

  await sequelize.close();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
